import React,{useEffect,useMemo,useState}from'react';
import{Routes,Route,Link,useNavigate,useParams,useLocation}from'react-router-dom';
import{api,user,session,logout}from'./api.js';
import {argentinaInputToIso,toArgentinaInput,assignmentPairName,resultScoreText,canEditResult} from './leagueUi.js';

const fmt=v=>v?new Intl.DateTimeFormat('es-AR',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Argentina/Buenos_Aires'}).format(new Date(v)):'-';
const err=e=>e.response?.data?.error||'No se pudo completar la acción.';
const eventText=e=>{const d=e?.data||{};if(e?.event_type==='wheel_v3_movement'){if(d.fromCategory!=null&&d.toCategory!=null)return `${d.reason==='promotion'?'Ascenso':'Descenso'}: ${d.fromCategory}ª → ${d.toCategory}ª.`;if(d.fromPosition!=null&&d.toPosition!=null)return `Posición: #${d.fromPosition} → #${d.toPosition}.`;return 'LA RED actualizó tu posición competitiva.';}if(e?.event_type==='ladder_swap')return `Ganaste una posición: #${d.from} → #${d.to}.`;if(e?.event_type==='position_penalty')return 'Penalización de posición/deuda aplicada.';if(e?.event_type==='promotion')return `Ascenso: ${d.from}ª → ${d.to}ª.`;if(e?.event_type==='relegation')return `Descenso: ${d.from}ª → ${d.to}ª.`;if(e?.event_type==='assignment_created')return 'La rueda asignó un nuevo rival.';if(e?.event_type==='schedule_proposed')return 'Se registró una nueva propuesta de fecha y lugar.';if(e?.event_type==='schedule_accepted')return 'Fecha, hora y lugar quedaron confirmados.';if(e?.event_type==='result_submitted')return 'Se cargó una versión del resultado.';if(e?.event_type==='result_revised')return 'Se corrigió la versión del resultado.';if(e?.event_type==='match_confirmed')return 'El resultado quedó oficial.';return 'LA RED registró un cambio competitivo.';};
function Layout({children,transparent=false}){const u=user();const initials=[u?.first_name,u?.last_name].filter(Boolean).map(v=>String(v).trim()[0]).join('').slice(0,2).toUpperCase()||'LR';return <div className="app"><header className={`header ${transparent?'header-transparent':''}`}><Link className="brand" to="/"><span>LA RED</span><small>TENIS · SAN PEDRO</small></Link><nav className="nav"><Link to="/">Inicio</Link><Link to="/ranking">Ranking</Link><Link to="/proximos">Próximos</Link>{u&&<Link to="/liga">Mi liga</Link>}{u&&<Link to="/pareja">Pareja</Link>}{u&&<Link to="/notificaciones">Avisos</Link>}{u&&<Link to="/cuenta">Cuenta</Link>}{u?.role==='admin'&&<Link to="/admin">Admin</Link>}</nav><div className="header-actions">{u?<><Link className="header-profile" to="/cuenta"><span className="header-avatar">{initials}</span><span className="header-profile-copy"><small>MI CUENTA</small><strong>{u.first_name||'Jugador'}</strong></span></Link><button className="header-exit" onClick={logout}><span>Salir</span><b>↗</b></button></>:<><Link className="header-link" to="/ingresar">Ingresar</Link><Link className="header-create" to="/ingresar?registro=1">Crear cuenta</Link></>}</div></header>{children}</div>}
function Notice({n}){return n?<div className={`notice ${n.type||''}`}>{n.text}</div>:null;}
function Home(){const[up,setUp]=useState([]),[records,setRecords]=useState([]),[recent,setRecent]=useState([]),[rows,setRows]=useState([]),[venues,setVenues]=useState([]),[gender,setGender]=useState('masculino');useEffect(()=>{api.get('/upcoming').then(r=>setUp(r.data||[])).catch(()=>setUp([]));api.get('/records').then(r=>setRecords(r.data||[])).catch(()=>setRecords([]));api.get('/results/recent').then(r=>setRecent(r.data||[])).catch(()=>setRecent([]));api.get('/ranking').then(r=>setRows(r.data||[])).catch(()=>setRows([]));api.get('/venues').then(r=>setVenues(r.data||[])).catch(()=>setVenues([]));},[]);const top=useMemo(()=>rows.filter(r=>r.slug===gender).sort((a,b)=>Number(a.number)-Number(b.number)||Number(a.position)-Number(b.position)).slice(0,10),[rows,gender]);return <Layout transparent><main><section className="home-hero"><div className="hero-photo"/><div className="hero-overlay"/><div className="hero-top-tags"><span>LA RED</span><span>LIGA DE TENIS</span><span>SAN PEDRO</span></div><div className="hero-layout"><div className="hero-copy"><div className="hero-mini">LA RED TENIS · SAN PEDRO</div><h1>La Red<span>TENIS · SAN PEDRO</span></h1><p>Una liga continua por parejas, automática y transparente. La posición se conquista en cancha.</p><div className="hero-buttons"><Link className="button button-green" to="/ranking">VER RANKING</Link><Link className="button button-outline" to="/ingresar?registro=1">QUIERO JUGAR</Link></div></div><aside className="top-card"><div className="top-card-header"><h2>TOP 10</h2><select value={gender} onChange={e=>setGender(e.target.value)}><option value="masculino">Masculino</option><option value="femenino">Femenino</option></select></div><div className="top-list">{top.length===0&&<div className="top-empty">Todavía no hay parejas en este ranking.</div>}{top.map((r,i)=><Link to={`/parejas/${r.pair_id}`} className="top-row" key={r.pair_id}><span className={`top-position ${i===0?'first':''}`}>{i+1}</span><div className="top-player"><strong>{r.players}</strong><small>{r.number}ª · posición #{r.position}</small></div><span className="top-role">{r.role==='attack'?'Ataque':r.role==='defense'?'Defensa':r.competition_state==='paused'?'Inactiva':'En rueda'}</span></Link>)}</div><Link className="top-link" to="/ranking">Ver ranking completo <span>→</span></Link></aside></div><div className="feature-grid"><article className="feature-card"><div className="feature-icon blue">◎</div><h3>RUEDA AUTOMÁTICA</h3><p>LA RED te asigna rival sin que tengas que buscarlo.</p></article><article className="feature-card"><div className="feature-icon green">◷</div><h3>COORDINACIÓN</h3><p>Fecha, hora y cancha quedan registradas y confirmadas.</p></article><article className="feature-card"><div className="feature-icon blue">▥</div><h3>RESULTADOS</h3><p>Cargá, confirmá y dejá que el motor aplique el movimiento.</p></article><article className="feature-card"><div className="feature-icon green">◉</div><h3>LA RED</h3><p>Ranking, próximos partidos, perfiles y récords públicos.</p></article></div></section><section className="home-rules"><div className="rules-title"><span>CÓMO FUNCIONA</span><h2>Jugá. Ganá.<br/>Subí.</h2></div><div className="rules"><article><strong>01</strong><h3>Formá tu pareja</h3><p>Ambos aceptan la invitación y LA RED determina la categoría competitiva correspondiente.</p></article><article><strong>02</strong><h3>Recibí tu rival</h3><p>La rueda asigna automáticamente un partido y abre un plazo máximo de 30 días para jugar y cargar resultado.</p></article><article><strong>03</strong><h3>Conquistá posiciones</h3><p>Si una pareja de abajo vence a una de arriba, intercambian lugares. La posición es el ranking.</p></article></div></section><section className="home-content"><div className="home-section-title"><span className="section-label">CARTELERA</span><h2>Esta semana en LA RED</h2></div><div className="grid3">{up.slice(0,6).map(m=><article className="card" key={m.id}><span className="eyebrow">{m.category_number}ª · {m.slug}</span><h3>{m.pair_a}<br/>vs.<br/>{m.pair_b}</h3><p>{fmt(m.scheduled_at)} · {m.location_text}</p></article>)}{!up.length&&<div className="empty">Todavía no hay partidos públicos confirmados.</div>}</div></section><section className="home-content"><div className="home-section-title"><span className="section-label">ÚLTIMOS PARTIDOS</span><h2>Resultados recientes</h2></div><div className="grid3">{recent.slice(0,6).map(m=><article className="card" key={m.id}><span className="eyebrow">{m.category_number}ª · {m.slug}</span><h3>{m.pair_a}<br/>vs.<br/>{m.pair_b}</h3><p>{m.result_type==='injury_abandonment'?'Lesión / abandono':m.result_type==='dissolution_forfeit'?'Forfeit por disolución':m.result_type==='administrative_forfeit'?'Resultado administrativo':'Resultado oficial'} · {fmt(m.played_at)}</p></article>)}{!recent.length&&<div className="empty">Todavía no hay resultados oficiales.</div>}</div></section><section className="home-content records-section"><div className="home-section-title"><span className="section-label">PRIMERA</span><h2>Récords históricos</h2></div><div className="grid2">{records.map(r=><article className="record-card" key={r.slug}><span>PRIMERA {r.slug?.toUpperCase()}</span><strong>{r.holders?.length?r.holders.map(h=>h.pair_name).filter(Boolean).join(' · '):(r.pair_name||'Sin récord todavía')}</strong><b>{r.defenses?`${r.defenses} defensas`:'—'}</b><small>{r.defenses?'Récord de defensas del #1 en un mismo reinado.':'Aparecerá cuando exista actividad oficial.'}</small></article>)}</div></section>{venues.length>0&&<section className="home-content"><div className="home-section-title"><span className="section-label">SEDES ADHERIDAS</span><h2>Canchas adheridas a LA RED</h2></div><div className="grid3">{venues.map(v=><article className="card" key={v.id}><span className="eyebrow">CANCHA ADHERIDA</span><h3>{v.name}</h3>{v.address&&<p>{v.address}</p>}<div className="actions">{v.instagram&&<a className="button secondary" href={v.instagram} target="_blank" rel="noreferrer">INSTAGRAM</a>}{v.booking_enabled&&v.booking_url&&<a className="button primary" href={v.booking_url} target="_blank" rel="noreferrer">RESERVAR</a>}</div></article>)}</div><p className="muted">Solo aparecen sedes incorporadas por LA RED. Un lugar escrito por jugadores al coordinar un partido no se publica automáticamente como adherido.</p></section>}<footer className="footer"><div><strong>LA RED TENIS · SAN PEDRO</strong><span>Más tenis. Más comunidad.</span></div><div className="footer-links"><Link to="/ranking">Ranking</Link><Link to="/proximos">Próximos</Link><Link to="/instalar">Instalar app</Link></div></footer></main></Layout>}
function Auth(){const nav=useNavigate();const location=useLocation();const registerMode=new URLSearchParams(location.search).get('registro')==='1';const[mode,setMode]=useState(registerMode?'register':'login'),[form,setForm]=useState({gender:'male',legalAcceptances:{}}),[acceptedLegal,setAcceptedLegal]=useState(false),[notice,setNotice]=useState(),[loading,setLoading]=useState(false),[dniInputKeys,setDniInputKeys]=useState({front:0,back:0});useEffect(()=>{api.get('/legal/versions').then(r=>setForm(f=>({...f,legalAcceptances:r.data})))},[]);useEffect(()=>{setMode(registerMode?'register':'login');setNotice();},[registerMode]);async function submit(e){e.preventDefault();if(mode==='register'&&!acceptedLegal){setNotice({type:'error',text:'Debés aceptar los documentos y confirmar que sos mayor de 18 años.'});return;}if(mode==='register'&&(!form.dniFront||!form.dniBack)){setNotice({type:'error',text:'Tenés que adjuntar una foto del frente y otra del dorso del DNI.'});return;}try{setLoading(true);setNotice();let response;if(mode==='register'){const data=new FormData();for(const key of ['firstName','lastName','phone','gender','dni','password'])data.append(key,form[key]||'');data.append('legalAcceptances',JSON.stringify(form.legalAcceptances||{}));data.append('dniFront',form.dniFront);data.append('dniBack',form.dniBack);response=await api.post('/auth/register',data);}else response=await api.post('/auth/login',form);session(response.data);nav('/liga');}catch(e){setNotice({type:'error',text:err(e)});}finally{setLoading(false)}}return <Layout><main className="center"><section className="auth card"><span className="eyebrow">LA RED</span><h1>{mode==='login'?'Ingresar':'Crear cuenta'}</h1><form onSubmit={submit}>{mode==='register'&&<><div className="grid2"><label>Nombre<input required onChange={e=>setForm({...form,firstName:e.target.value})}/></label><label>Apellido<input required onChange={e=>setForm({...form,lastName:e.target.value})}/></label></div><label>WhatsApp<input required onChange={e=>setForm({...form,phone:e.target.value})}/></label><label>Circuito<select value={form.gender} onChange={e=>setForm({...form,gender:e.target.value})}><option value="male">Masculino</option><option value="female">Femenino</option></select></label><label>DNI (será tu usuario)<input required inputMode="numeric" onChange={e=>setForm({...form,dni:e.target.value})}/></label><div className="identity-upload"><b>Verificación de identidad</b><p>Subí una foto clara del frente y otra del dorso de tu DNI. Solo administración puede verlas y se purgan de la base activa cuando tu identidad se verifica o rechaza.</p><div className="grid2"><div className="file-field"><label htmlFor="dni-front">Frente del DNI</label><div className="file-upload-control"><label className="file-picker" htmlFor="dni-front"><input id="dni-front" key={dniInputKeys.front} required type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={e=>setForm({...form,dniFront:e.target.files?.[0]||null})}/><span className="file-picker-button">Elegir archivo</span><span className="file-picker-name">{form.dniFront?.name||'Sin archivo'}</span></label>{form.dniFront&&<button className="file-clear" type="button" aria-label="Quitar foto del frente del DNI" title="Quitar foto" onClick={()=>{setForm(f=>({...f,dniFront:null}));setDniInputKeys(k=>({...k,front:k.front+1}))}}><span aria-hidden="true"/></button>}</div></div><div className="file-field"><label htmlFor="dni-back">Dorso del DNI</label><div className="file-upload-control"><label className="file-picker" htmlFor="dni-back"><input id="dni-back" key={dniInputKeys.back} required type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={e=>setForm({...form,dniBack:e.target.files?.[0]||null})}/><span className="file-picker-button">Elegir archivo</span><span className="file-picker-name">{form.dniBack?.name||'Sin archivo'}</span></label>{form.dniBack&&<button className="file-clear" type="button" aria-label="Quitar foto del dorso del DNI" title="Quitar foto" onClick={()=>{setForm(f=>({...f,dniBack:null}));setDniInputKeys(k=>({...k,back:k.back+1}))}}><span aria-hidden="true"/></button>}</div></div></div><small>Formatos: JPG, PNG o WEBP · máximo 5 MB por imagen.</small></div><div className="legal-box"><b>Antes de participar</b><p>Confirmás que sos mayor de 18 años, comprendés que el tenis implica riesgos físicos y aceptás las reglas, conducta, privacidad y comunicaciones operativas.</p><div className="legal-links"><a href="/legal/terms.md" target="_blank">Términos</a><a href="/legal/risks.md" target="_blank">Riesgos</a><a href="/legal/conduct.md" target="_blank">Conducta</a><a href="/legal/privacy.md" target="_blank">Privacidad</a><a href="/legal/whatsapp.md" target="_blank">WhatsApp</a></div><label className="check"><input type="checkbox" checked={acceptedLegal} onChange={e=>setAcceptedLegal(e.target.checked)}/><span>Confirmo que soy mayor de 18 años y acepto estos documentos.</span></label></div></>} {mode==='login'&&<label>DNI<input required inputMode="numeric" onChange={e=>setForm({...form,dni:e.target.value})}/></label>}<label>Contraseña<input required minLength="8" type="password" onChange={e=>setForm({...form,password:e.target.value})}/></label><button className="button primary" disabled={loading}>{loading?'Cargando...':'CONTINUAR'}</button></form><Notice n={notice}/><button className="link-button" type="button" onClick={()=>nav(mode==='login'?'/ingresar?registro=1':'/ingresar')}>{mode==='login'?'Crear una cuenta':'Ya tengo cuenta'}</button>{mode==='login'&&<Link className="link-button" to="/recuperar">Olvidé mi contraseña</Link>}</section></main></Layout>}

function AdminLogin(){const nav=useNavigate();const[form,setForm]=useState({}),[notice,setNotice]=useState(),[loading,setLoading]=useState(false);async function submit(e){e.preventDefault();try{setLoading(true);setNotice();const r=await api.post('/auth/admin-login',form);session(r.data);nav('/admin');}catch(e){setNotice({type:'error',text:'Acceso no autorizado.'});}finally{setLoading(false)}}return <div className="admin-login-shell"><main className="admin-login-wrap"><section className="admin-login-card"><div className="admin-login-brand"><span>LA RED</span><small>CONTROL</small></div><span className="eyebrow">ACCESO PRIVADO</span><h1>Administración</h1><p>Acceso reservado.</p><form onSubmit={submit}><label>DNI<input required autoComplete="username" inputMode="numeric" onChange={e=>setForm({...form,dni:e.target.value})}/></label><label>Contraseña<input required autoComplete="current-password" minLength="8" type="password" onChange={e=>setForm({...form,password:e.target.value})}/></label><label>Código de seguridad<input required inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} placeholder="6 dígitos" value={form.totp||''} onChange={e=>setForm({...form,totp:e.target.value.replace(/\D/g,'').slice(0,6)})}/></label><button className="button primary" disabled={loading}>{loading?'Validando...':'INGRESAR'}</button></form><Notice n={notice}/></section></main></div>}

function Recovery(){const[dni,setDni]=useState(''),[code,setCode]=useState(''),[password,setPassword]=useState(''),[sent,setSent]=useState(false),[n,setN]=useState();async function request(){try{await api.post('/auth/recovery/request',{dni});setSent(true);setN({text:'Si el DNI existe, enviamos un código al WhatsApp registrado.'});}catch(e){setN({type:'error',text:err(e)})}}async function reset(){try{await api.post('/auth/recovery/reset',{dni,code,password});setN({text:'Contraseña actualizada. Ya podés ingresar.'});}catch(e){setN({type:'error',text:err(e)})}}return <Layout><main className="center"><section className="card auth"><h1>Recuperar acceso</h1><label>DNI<input value={dni} onChange={e=>setDni(e.target.value)}/></label>{!sent?<button className="button primary" onClick={request}>ENVIAR CÓDIGO</button>:<><label>Código<input value={code} onChange={e=>setCode(e.target.value)}/></label><label>Nueva contraseña<input type="password" minLength="8" value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="button primary" onClick={reset}>CAMBIAR CONTRASEÑA</button></>}<Notice n={n}/></section></main></Layout>}
function Ranking(){const[rows,setRows]=useState([]),[slug,setSlug]=useState('masculino'),[cat,setCat]=useState(1),[loaded,setLoaded]=useState(false),[n,setN]=useState();async function load(){setN();setLoaded(false);try{setRows((await api.get('/ranking')).data||[]);setLoaded(true)}catch(e){setN({type:'error',text:err(e)})}}useEffect(()=>{load()},[]);const filtered=rows.filter(r=>r.slug===slug&&Number(r.number)===Number(cat));return <Layout><main className="page ranking-page"><div className="page-title"><div><span className="eyebrow">LA RED</span><h1>Ranking</h1><p>La posición define el ranking.</p></div><div className="filters"><select aria-label="Circuito" value={slug} onChange={e=>setSlug(e.target.value)}><option>masculino</option><option>femenino</option></select><select aria-label="Categoría" value={cat} onChange={e=>setCat(e.target.value)}>{[1,2,3,4,5,6,7].map(n=><option key={n} value={n}>{n}ª</option>)}</select></div></div><Notice n={n}/>{n&&<button onClick={load}>REINTENTAR</button>}{!loaded&&!n&&<p>Cargando ranking...</p>}{loaded&&!filtered.length&&<div className="empty">Todavía no hay parejas en esta categoría y circuito.</div>}<div className="ranking"><div className="rank-head"><span>#</span><span>Pareja</span><span>Rol</span><span>PJ</span><span>PG</span><span>Games</span></div>{filtered.map(r=><Link to={`/parejas/${r.pair_id}`} className="rank-row" key={r.pair_id}><b>{r.position}</b><strong>{r.players}{r.competition_state==='paused'&&<small> · pausada</small>}</strong><span>{r.role==='attack'?'Ataque':r.role==='defense'?'Defensa':'—'}</span><span>{r.played}</span><span>{r.wins}</span><span>{r.game_diff}</span></Link>)}</div><div className="help"><b>¿Cómo funciona?</b><p>Si una pareja ubicada más abajo vence a una que está arriba, intercambian posiciones. Las estadísticas no reordenan globalmente la escalera.</p></div></main></Layout>}
function PairProfile(){const{id}=useParams(),[d,setD]=useState(),[n,setN]=useState();async function load(){setN();try{setD((await api.get(`/pairs/${id}/profile`)).data)}catch(e){setN({type:'error',text:err(e)})}}useEffect(()=>{setD();load()},[id]);if(!d)return <Layout><main className="page">{n?<><Notice n={n}/><button onClick={load}>REINTENTAR</button></>:"Cargando..."}</main></Layout>;return <Layout><main className="page pair-profile-page"><div className="page-title"><div><span className="eyebrow">PERFIL DEPORTIVO</span><h1>{d.pair.players}</h1><p>{d.pair.number}ª {d.pair.slug} · #{d.pair.position}</p></div></div>{d.upcoming&&<article className="card featured-match-card"><span className="eyebrow">PRÓXIMO PARTIDO</span><h3>{fmt(d.upcoming.scheduled_at)} · {d.upcoming.location_text}</h3></article>}<div className="grid3 profile-stats"><article className="card stat-card"><b>Partidos</b><h2>{d.pair.played}</h2></article><article className="card stat-card"><b>Victorias</b><h2>{d.pair.wins}</h2></article><article className="card stat-card"><b>Estado</b><h2>{d.pair.competition_state==='paused'?'Pausada':'Activa'}</h2></article></div><section className="page-section"><div className="section-heading"><div><span className="eyebrow">HISTORIAL</span><h2>Últimos resultados</h2></div></div><div className="stack">{d.matches.map(m=><article className="card compact" key={m.id}><b>{Number(m.winner_pair_id)===Number(id)?'Victoria':'Derrota'} · {m.result_type==='injury_abandonment'?'Lesión / abandono':'Resultado oficial'}</b><span>{fmt(m.played_at)}</span></article>)}{!d.matches.length&&<div className="empty">Todavía no hay resultados oficiales.</div>}</div></section><section className="page-section"><div className="section-heading"><div><span className="eyebrow">MOVIMIENTOS</span><h2>Historia competitiva</h2></div></div><div className="stack">{d.events.map((e,i)=><article className="card compact" key={i}><b>{eventText(e)}</b><span>{fmt(e.created_at)}</span></article>)}{!d.events.length&&<div className="empty">Todavía no hay movimientos competitivos.</div>}</div></section></main></Layout>}
function Upcoming(){const[rows,setRows]=useState([]),[slug,setSlug]=useState('todos'),[cat,setCat]=useState('todas'),[venue,setVenue]=useState('todos');useEffect(()=>{api.get('/upcoming').then(r=>setRows(r.data||[]))},[]);const venues=[...new Set(rows.map(r=>r.location_text).filter(Boolean))].sort();const filtered=rows.filter(r=>(slug==='todos'||r.slug===slug)&&(cat==='todas'||Number(r.category_number)===Number(cat))&&(venue==='todos'||r.location_text===venue));return <Layout><main className="page upcoming-page"><div className="page-title"><div><h1>Próximos partidos</h1><p>Solo aparecen programaciones aceptadas por ambas parejas.</p></div><div className="filters"><select value={slug} onChange={e=>setSlug(e.target.value)}><option value="todos">Todos</option><option value="masculino">Masculino</option><option value="femenino">Femenino</option></select><select value={cat} onChange={e=>setCat(e.target.value)}><option value="todas">Todas</option>{[1,2,3,4,5,6,7].map(n=><option key={n} value={n}>{n}ª</option>)}</select><select value={venue} onChange={e=>setVenue(e.target.value)}><option value="todos">Todos los lugares</option>{venues.map(v=><option key={v}>{v}</option>)}</select></div></div><div className="grid3 upcoming-grid">{filtered.map(r=><article className="card upcoming-card" key={r.id}><span className="eyebrow">{r.category_number}ª · {r.slug}</span><h3>{r.pair_a}<br/>vs.<br/>{r.pair_b}</h3><p>{fmt(r.scheduled_at)}<br/>{r.location_text}</p></article>)}{!filtered.length&&<div className="empty">No hay partidos públicos que coincidan con estos filtros.</div>}</div></main></Layout>}
function PairManager(){
  const[d,setD]=useState(),[partner,setPartner]=useState(''),[cat,setCat]=useState(7),[n,setN]=useState();
  async function load(){try{setD((await api.get('/me/pair')).data)}catch(e){setN({type:'error',text:err(e)})}}
  useEffect(()=>{load()},[]);
  async function run(fn,msg){try{await fn();setN({text:msg});await load()}catch(e){setN({type:'error',text:err(e)})}}
  if(!d)return <Layout><main className="page">{n?<><Notice n={n}/><button onClick={load}>REINTENTAR</button></>:"Cargando..."}</main></Layout>;
  const isV3=d.engine==='wheel-v3';
  const pauseMine=d.pauseRequest&&Number(d.pauseRequest.requested_by_user_id)===Number(d.user.id);
  const dissolveMine=d.dissolutionRequest&&Number(d.dissolutionRequest.requested_by_user_id)===Number(d.user.id);
  return <Layout><main className="page pair-page">
    <div className="page-title pair-title"><div><span className="eyebrow">TU EQUIPO</span><h1>Mi pareja</h1><p>Formá tu equipo, aceptá invitaciones y administrá su estado competitivo.</p></div></div>
    {d.user.verification_status!=='verified'&&<div className="notice pair-verification-note">Tu identidad está pendiente de verificación. Podés recorrer LA RED, pero todavía no formar pareja ni competir.</div>}
    {d.pair?<section className="page-section">
      <article className="card pair-current-card"><div><span className="eyebrow">{d.pair.category_number}ª · {d.pair.league_slug}</span><h2>{d.pair.members.map(m=>`${m.first_name} ${m.last_name}`).join(' / ')}</h2><p>Posición #{d.pair.position} · {isV3?(d.pair.competition_state==='paused'?'inactiva':d.pair.competition_state==='active'?'activa':d.pair.competition_state):d.pair.competition_state}</p></div><div className="pair-state-badge">{isV3?(d.pair.competition_state==='paused'?'Inactiva':d.pair.competition_state==='active'?'Activa':d.pair.competition_state):d.pair.competition_state}</div></article>
      <div className="actions pair-actions">
        {isV3&&d.pair.competition_state==='active'&&!d.pair.pause_after_current&&<button className="button secondary" onClick={()=>confirm(d.hasOpenAssignment?'La pareja quedará inactiva cuando se resuelva el partido actual. ¿Continuar?':'¿Pasar la pareja a inactiva?')&&run(()=>api.post('/me/pair/pause',{}),d.hasOpenAssignment?'Inactividad registrada para después del partido.':'Pareja inactiva.')}>{d.hasOpenAssignment?'PASAR A INACTIVA AL CERRAR':'PASAR A INACTIVA'}</button>}
        {!isV3&&d.pair.competition_state==='active'&&!d.pair.pause_after_current&&!d.pauseRequest&&<button className="button secondary" onClick={()=>run(()=>api.post('/me/pair/pause',{afterCurrent:Boolean(d.hasOpenAssignment)}),d.hasOpenAssignment?'Solicitud de pausa al terminar registrada.':'Solicitud de pausa registrada.')}>{d.hasOpenAssignment?'PAUSAR AL TERMINAR':'PEDIR PAUSA'}</button>}
        {!isV3&&d.pair.competition_state==='active'&&d.pauseRequest&&pauseMine&&<button className="button secondary" disabled>PAUSA SOLICITADA · ESPERANDO COMPAÑERO</button>}
        {!isV3&&d.pair.competition_state==='active'&&d.pauseRequest&&!pauseMine&&<button className="button secondary" onClick={()=>run(()=>api.post('/me/pair/pause',{afterCurrent:Boolean(d.hasOpenAssignment)}),'Pausa confirmada.')}>CONFIRMAR PAUSA</button>}
        {d.pair.pause_after_current&&<button className="button secondary" disabled>{isV3?'INACTIVIDAD PENDIENTE · AL CERRAR EL PARTIDO':'PAUSA CONFIRMADA · AL CERRAR EL PARTIDO'}</button>}
        {d.pair.competition_state==='paused'&&<button className="button secondary" onClick={()=>run(()=>api.post('/me/pair/reactivate'),'Pareja reactivada.')}>REACTIVAR</button>}
        {!d.dissolutionRequest&&<button className="button danger" onClick={()=>confirm('¿Iniciar la disolución? Tu compañero deberá confirmarla o se resolverá según los plazos de LA RED.')&&run(()=>api.post('/me/pair/dissolve'),'Solicitud de disolución registrada.')}>PEDIR DISOLUCIÓN</button>}
        {d.dissolutionRequest?.status==='pending'&&dissolveMine&&<button className="button danger" disabled>DISOLUCIÓN SOLICITADA · ESPERANDO COMPAÑERO</button>}
        {d.dissolutionRequest?.status==='pending'&&!dissolveMine&&<button className="button danger" onClick={()=>confirm('Tu compañero pidió disolver la pareja. ¿Confirmás?')&&run(()=>api.post('/me/pair/dissolve'),'Disolución confirmada.')}>CONFIRMAR DISOLUCIÓN</button>}
        {d.dissolutionRequest&&d.dissolutionRequest.status!=='pending'&&<button className="button danger" disabled>DISOLUCIÓN CONFIRMADA · PENDIENTE DE CIERRE</button>}
      </div>
      {!isV3&&d.pauseRequest&&<p className="muted">{pauseMine?'Tu compañero recibió el pedido de pausa y debe confirmarlo.':'Tu compañero pidió pausar la pareja. Confirmá desde este botón si estás de acuerdo.'}</p>}
      {d.dissolutionRequest?.status==='pending'&&<p className="muted">{dissolveMine?`Esperando confirmación. Salida unilateral disponible al vencer el plazo: ${fmt(d.dissolutionRequest.deadline_at)}.`:'Tu compañero inició la disolución. Podés confirmarla desde esta pantalla.'}</p>}
    </section>:<>
      <section className="pair-setup-grid"><article className="card form-card"><span className="eyebrow">FORMAR PAREJA</span><h2>Elegí compañero/a</h2><p className="card-intro">Solo aparecen jugadores verificados de tu mismo circuito que estén disponibles.</p><label>Jugador<select value={partner} onChange={e=>setPartner(e.target.value)}><option value="">Elegir jugador</option>{d.available.map(p=><option key={p.id} value={p.id}>{p.first_name} {p.last_name} · {p.current_category_number?`${p.current_category_number}ª`:'nuevo/a'}</option>)}</select></label><label>Categoría si ambos son nuevos<select value={cat} onChange={e=>setCat(e.target.value)}>{[1,2,3,4,5,6,7].map(x=><option key={x}>{x}</option>)}</select></label><button className="button primary" disabled={d.user.verification_status!=='verified'||!partner||d.outgoing.length>0} onClick={()=>run(()=>api.post('/pair-invitations',{inviteeUserId:Number(partner),category:Number(cat)}),'Invitación enviada.')}>{d.outgoing.length?'INVITACIÓN PENDIENTE':'ENVIAR INVITACIÓN'}</button></article>
      <aside className="card pair-guide-card"><span className="eyebrow">CÓMO SIGUE</span><div className="pair-guide-step"><b>01</b><div><strong>Invitación</strong><p>Elegís a otro jugador disponible.</p></div></div><div className="pair-guide-step"><b>02</b><div><strong>Aceptación</strong><p>La otra persona confirma desde su cuenta.</p></div></div><div className="pair-guide-step"><b>03</b><div><strong>Rueda</strong><p>LA RED crea la pareja y empieza a buscar rival.</p></div></div></aside></section>
      <section className="page-section invitations-section"><div className="section-heading"><div><span className="eyebrow">ENVIADA</span><h2>Invitación enviada</h2></div><small>{d.outgoing.length} pendientes</small></div><div className="stack">{d.outgoing.map(i=><article className="card compact invitation-row" key={i.id}><div><b>{i.first_name} {i.last_name}</b><p>Pareja resultante en {i.resulting_category_number}ª · vence {fmt(i.expires_at)}</p></div><button className="button danger" onClick={()=>confirm('¿Cancelar esta invitación de pareja?')&&run(()=>api.patch(`/pair-invitations/${i.id}/cancel`),'Invitación cancelada.')}>CANCELAR</button></article>)}{!d.outgoing.length&&<div className="empty">No tenés invitaciones enviadas pendientes.</div>}</div></section>
      <section className="page-section invitations-section"><div className="section-heading"><div><span className="eyebrow">PENDIENTES</span><h2>Invitaciones recibidas</h2></div><small>{d.incoming.length} pendientes</small></div><div className="stack">{d.incoming.map(i=><article className="card compact invitation-row" key={i.id}><div><b>{i.first_name} {i.last_name}</b><p>Pareja resultante en {i.resulting_category_number}ª</p></div><button onClick={()=>run(()=>api.patch(`/pair-invitations/${i.id}/accept`),'Pareja formada.')}>ACEPTAR</button></article>)}{!d.incoming.length&&<div className="empty">No tenés invitaciones pendientes.</div>}</div></section>
    </>}
    <Notice n={n}/>
  </main></Layout>
}
function League(){
  const[d,setD]=useState(),[n,setN]=useState(),[schedule,setSchedule]=useState({locationText:''}),[result,setResult]=useState({resultType:'normal',sets:[{pairA:6,pairB:4,kind:'set'},{pairA:6,pairB:4,kind:'set'}]}),[report,setReport]=useState({target:'pair',reason:'misconduct',details:''}),[recentReport,setRecentReport]=useState({assignmentId:'',target:'pair',reason:'misconduct',details:''});
  function setScore(i,key,value){setResult(r=>({...r,sets:r.sets.map((s,j)=>j===i?{...s,[key]:Number(value)}:s)}))}
  function addThird(){setResult(r=>({...r,sets:r.sets.length===3?r.sets:[...r.sets,{pairA:6,pairB:4,kind:'set'}]}))}
  function removeThird(){setResult(r=>({...r,sets:r.sets.slice(0,2)}))}
  async function load(){try{const data=(await api.get('/me/league')).data;setD({...data,_receivedMono:globalThis.performance?.now?.()??0})}catch(e){setN({type:'error',text:err(e)})}}
  useEffect(()=>{load()},[]);
  useEffect(()=>{const v=d?.assignment?.myVersion;if(v&&!d?.assignment?.otherVersion){setResult({resultType:v.result_type,winnerPairId:Number(v.winner_pair_id),playedAt:toArgentinaInput(v.played_at),abandonedPairId:v.abandoned_pair_id?Number(v.abandoned_pair_id):undefined,sets:v.score?.sets?.length?v.score.sets:[{pairA:6,pairB:4,kind:'set'},{pairA:6,pairB:4,kind:'set'}]})}},[d?.assignment?.myVersion?.id,d?.assignment?.otherVersion?.id]);
  async function run(fn,msg){try{await fn();setN({text:msg});await load()}catch(e){setN({type:'error',text:err(e)})}}
  if(!d)return <Layout><main className="page">{n?<><Notice n={n}/><button onClick={load}>REINTENTAR</button></>:"Cargando..."}</main></Layout>;
  if(!d.pair){const pending=d.user?.verification_status==='pending';const resubmit=Boolean(d.user?.identity_resubmit_reason);const first=d.user?.first_name||user()?.first_name||'Jugador';return <Layout><main className="page league-onboarding-page"><section className="league-onboarding-hero"><div className="league-onboarding-copy"><span className="eyebrow">MI LIGA · PRIMEROS PASOS</span><h1>{resubmit?'Necesitamos una nueva foto de tu DNI.':pending?`Bienvenido a LA RED, ${first}.`:'Tu liga empieza acá.'}</h1><p className="lead">{resubmit?`Administración no pudo validar las imágenes anteriores. Motivo: ${d.user.identity_resubmit_reason}`:pending?'Tu cuenta ya está creada y tu identidad está en revisión. Mientras tanto podés conocer el ranking y la cartelera; no corre ningún plazo deportivo.':'Tu identidad ya está verificada. El próximo paso es formar tu pareja y entrar a la rueda automática.'}</p><div className="actions">{pending?<><Link className="button button-green" to="/cuenta">{resubmit?'REENVIAR DOCUMENTACIÓN':'VER MI CUENTA'}</Link><Link className="button button-outline" to="/ranking">RECORRER RANKING</Link></>:<><Link className="button button-green" to="/pareja">FORMAR MI PAREJA</Link><Link className="button button-outline" to="/ranking">VER RANKING</Link></>}</div></div><aside className={`league-account-status ${resubmit?'is-resubmit':pending?'is-pending':'is-ready'}`}><span className="league-status-kicker">ESTADO DE TU CUENTA</span><div className="league-status-icon">{resubmit?'!':pending?'◷':'✓'}</div><strong>{resubmit?'FOTOS A REENVIAR':pending?'IDENTIDAD EN REVISIÓN':'IDENTIDAD VERIFICADA'}</strong><p>{resubmit?d.user.identity_resubmit_reason:pending?'Administración está revisando tu documentación. Si notás que subiste mal una foto, podés reemplazarla desde Mi cuenta.':'Ya podés formar pareja con otro jugador verificado de tu circuito.'}</p><div className="league-status-meta"><span><small>PAREJA</small><b>Pendiente</b></span><span><small>PLAZOS ACTIVOS</small><b>0</b></span></div></aside></section><section className="league-progress"><article className="league-step done"><span>01</span><div><small>LISTO</small><h3>Cuenta creada</h3><p>Tu acceso ya está activo.</p></div></article><article className={`league-step ${pending?'active':'done'}`}><span>02</span><div><small>{resubmit?'ACCIÓN REQUERIDA':pending?'AHORA':'LISTO'}</small><h3>Verificación</h3><p>{resubmit?'Reenviá frente y dorso para continuar.':pending?'Estamos comprobando tu identidad.':'Identidad confirmada.'}</p></div></article><article className={`league-step ${pending?'locked':'active'}`}><span>03</span><div><small>{pending?'DESPUÉS':'SIGUIENTE'}</small><h3>Formar pareja</h3><p>Invitación + aceptación entre dos jugadores.</p></div></article><article className="league-step locked"><span>04</span><div><small>DESPUÉS</small><h3>Entrar a la rueda</h3><p>LA RED te asigna rival automáticamente.</p></div></article></section><section className="grid3 league-onboarding-info"><article className="card"><span className="eyebrow">SIN PRESIÓN</span><h3>No hay reloj corriendo</h3><p>Hasta que exista un partido asignado, no hay vencimientos ni sanciones por inactividad.</p></article><article className="card"><span className="eyebrow">PRIVACIDAD</span><h3>Tu identidad es privada</h3><p>Ranking, perfiles y próximos partidos no muestran DNI ni WhatsApp.</p></article><article className="card"><span className="eyebrow">AUTOMÁTICO</span><h3>Después trabaja la rueda</h3><p>Con la pareja lista, LA RED busca rival y te muestra siempre qué acción sigue.</p></article></section></main></Layout>}
  const isV3=d.engine==='wheel-v3';
  const a=d.assignment;
  const now=isV3&&d.server_now?new Date(d.server_now).getTime()+Math.max(0,(globalThis.performance?.now?.()??d._receivedMono)-d._receivedMono):Date.now();
  const originalDeadline=a?new Date(a.deadline_at).getTime():0;
  const extensionOpen=Boolean(!isV3&&a&&!a.extraordinary_used&&now>=originalDeadline&&now<=originalDeadline+48*60*60*1000);
  const myExtensionVoted=Boolean(a?.extensionVotes?.includes(Number(d.pair.id)));
  const canNoShow=Boolean(a?.status==='open'&&!a?.first_result_at&&a?.schedule_confirmed_at&&a?.scheduled_at&&now>=new Date(a.scheduled_at).getTime()&&!a.noShow);
  const selectedRecent=(d.reportableRecent||[]).find(x=>Number(x.id)===Number(recentReport.assignmentId));
  const title=!a?(d.pair.competition_state==='paused'?'Tu pareja está inactiva':'Estás al día'):a.status==='result_pending'&&a.otherVersion&&!a.myVersion?'Confirmar resultado':a.status==='result_pending'&&a.myVersion?'Esperar confirmación / corregir resultado':a.status==='disputed'?'Esperar resolución':a.schedule_confirmed_at?'Jugar / cargar resultado':'Coordinar el partido';
  return <Layout><main className="page league-page">
    <span className="eyebrow">¿QUÉ TE TOCA HACER AHORA?</span><h1>{title}</h1><p className="lead">{d.pair.players} · {d.pair.category_number}ª · #{d.pair.position}{isV3&&d.pair.role?` · ${d.pair.role==='attack'?'Ataque':'Defensa'}`:''}</p>
    {a?<div className="grid2">
      <article className="card"><span className="eyebrow">PARTIDO ACTUAL</span><h2>vs. {a.rival.players}</h2><p>Vence: {fmt(isV3?a.deadline_at:(a.extraordinary_deadline_at||a.deadline_at))}</p>{a.schedule_confirmed_at&&<p><b>Oficial:</b> {fmt(a.scheduled_at)} · {a.location_text}</p>}<div className="actions">{a.rival.members.map(m=><a className="button secondary" key={m.id} href={`https://wa.me/${String(m.phone||'').replace(/\D/g,'')}`} target="_blank">WHATSAPP · {m.first_name}</a>)}</div>{a.pendingProposal&&<><p>Propuesta pendiente: {fmt(a.pendingProposal.scheduled_at)} · {a.pendingProposal.location_text}</p>{Number(a.pendingProposal.proposed_by_pair_id)!==Number(d.pair.id)?<button onClick={()=>run(()=>api.patch(`/assignments/${a.id}/schedule-proposals/${a.pendingProposal.id}/accept`),'Programación confirmada.')}>ACEPTAR PROPUESTA</button>:isV3&&<button className="secondary" onClick={()=>run(()=>api.patch(`/assignments/${a.id}/schedule-proposals/${a.pendingProposal.id}/cancel`),'Propuesta cancelada.')}>CANCELAR PROPUESTA</button>}</>}</article>
      {a.status==='open'&&!a.first_result_at&&<article className="card"><h2>Proponer fecha y lugar</h2><label>Día y hora (Argentina)<input type="datetime-local" onChange={e=>setSchedule({...schedule,scheduledAt:e.target.value})}/></label><label>Lugar / cancha<input maxLength={160} value={schedule.locationText||''} placeholder="Ej. Club Central, cancha 2" onChange={e=>setSchedule({...schedule,locationText:e.target.value})}/></label><small>Lugar informado por los jugadores. Su mención no implica vínculo comercial con LA RED.</small><button disabled={!schedule.scheduledAt||String(schedule.locationText||'').trim().length<2} onClick={()=>run(()=>api.post(`/assignments/${a.id}/schedule-proposals`,{...schedule,scheduledAt:argentinaInputToIso(schedule.scheduledAt)}),'Propuesta enviada.')}>PROPONER</button>{!isV3&&extensionOpen&&<button className="secondary" disabled={myExtensionVoted} onClick={()=>run(()=>api.post(`/assignments/${a.id}/extension-vote`),'Confirmación de causa externa registrada.')}>{myExtensionVoted?'CAUSA EXTERNA YA CONFIRMADA':'CONFIRMAR CAUSA EXTERNA'}</button>}{!isV3&&a.extraordinary_used&&<p className="muted">Extensión extraordinaria activa hasta {fmt(a.extraordinary_deadline_at)}.</p>}</article>}
      <article className="card"><h2>Resultado</h2>{a.confirmation_deadline_at&&<p>Revisión hasta: {fmt(a.confirmation_deadline_at)}</p>}{[a.myVersion,a.otherVersion].filter(Boolean).map(v=><div className="result-review" key={v.id}><b>{Number(v.pair_id)===Number(d.pair.id)?"Tu versión":"Versión del rival"}</b><p>Ganador: {assignmentPairName(v.winner_pair_id,d.pair,a)}</p><p>{resultScoreText(v)}</p><small>A: {assignmentPairName(a.pair_a_id,d.pair,a)} · B: {assignmentPairName(a.pair_b_id,d.pair,a)}</small>{v.abandoned_pair_id&&<p>Abandonó: {assignmentPairName(v.abandoned_pair_id,d.pair,a)}</p>}<p>Jugado: {fmt(v.played_at)}</p></div>)}{a.status==='disputed'?<div className="empty">Las dos versiones no coinciden. Administración debe resolver la disputa; no tenés que cargar nada más.</div>:canEditResult(a)&&<>{a.otherVersion&&!a.myVersion&&<><button className="button primary" onClick={()=>run(()=>api.patch(`/assignments/${a.id}/results/confirm`),'Resultado confirmado.')}>CONFIRMAR RESULTADO CARGADO</button><p>Si no coincide con lo jugado, cargá tu versión a continuación. Las versiones diferentes pasan a Administración.</p><h3>Cargar mi versión</h3></>}{a.myVersion&&<p className="muted">Tu resultado ya está cargado. Mientras el rival no responda, podés corregirlo volviendo a enviarlo.</p>}<label>Tipo<select value={result.resultType} onChange={e=>setResult({...result,resultType:e.target.value})}><option value="normal">Normal</option><option value="injury_abandonment">Lesión / abandono</option></select></label><label>Ganador<select value={result.winnerPairId||''} onChange={e=>setResult({...result,winnerPairId:Number(e.target.value)})}><option value="">Elegir</option><option value={d.pair.id}>Mi pareja</option><option value={a.rival.id}>{a.rival.players}</option></select></label><label>Fecha y hora jugada (Argentina)<input type="datetime-local" step="1" value={result.playedAt||''} onChange={e=>setResult({...result,playedAt:e.target.value})}/></label>{result.resultType==='normal'&&<div className="score-box"><b>Marcador</b><small>A: {assignmentPairName(a.pair_a_id,d.pair,a)} · B: {assignmentPairName(a.pair_b_id,d.pair,a)}</small>{result.sets.map((set,i)=><div className="score-row" key={i}><span>{i+1}º</span><input type="number" min="0" value={set.pairA} onChange={e=>setScore(i,'pairA',e.target.value)}/><input type="number" min="0" value={set.pairB} onChange={e=>setScore(i,'pairB',e.target.value)}/>{i===2&&<select value={set.kind} onChange={e=>setResult(r=>({...r,sets:r.sets.map((x,j)=>j===2?{...x,kind:e.target.value}:x)}))}><option value="set">Set</option><option value="match_tiebreak">Super tie-break</option></select>}</div>)}{result.sets.length===2?<button type="button" className="secondary" onClick={addThird}>AGREGAR TERCER PARCIAL</button>:<button type="button" className="secondary" onClick={removeThird}>QUITAR TERCER PARCIAL</button>}</div>}{result.resultType==='injury_abandonment'&&<label>Abandonó<select value={result.abandonedPairId||''} onChange={e=>setResult({...result,abandonedPairId:Number(e.target.value)})}><option value="">Elegir</option><option value={d.pair.id}>Mi pareja</option><option value={a.rival.id}>{a.rival.players}</option></select></label>}<button className="button primary" disabled={!result.winnerPairId||!result.playedAt||(result.resultType==='injury_abandonment'&&!result.abandonedPairId)} onClick={()=>run(()=>api.post(`/assignments/${a.id}/results`,{...result,playedAt:argentinaInputToIso(result.playedAt),score:result.resultType==='normal'?{sets:result.sets}:null}),'Resultado cargado.')}>{a.myVersion?'GUARDAR CORRECCIÓN':a.otherVersion?'ENVIAR MI VERSIÓN':'CARGAR RESULTADO'}</button></>}</article>
      <article className="card"><h2>Incidentes</h2>{isV3&&a.status==='open'&&!a.first_result_at&&<button className="button danger" onClick={()=>confirm('Esto reconoce un incumplimiento de tu pareja y cierra el partido administrativamente. ¿Continuar?')&&run(()=>api.post(`/assignments/${a.id}/cannot-play`),'Incumplimiento informado y partido resuelto.')}>NO PUDE JUGAR</button>}{canNoShow&&<button className="button secondary" onClick={()=>run(()=>api.post(`/assignments/${a.id}/no-show`),'No-show informado. Hay 48 h de reconsideración.')}>REPORTAR NO-SHOW</button>}{a.noShow&&Number(a.noShow.reported_by_pair_id)===Number(d.pair.id)&&a.noShow.status==='pending'&&<>{<p className="muted">No-show informado. Podés cancelarlo dentro de la ventana de 48 horas.</p>}{isV3&&<button className="button secondary" onClick={()=>run(()=>api.patch(`/assignments/${a.id}/no-show/cancel`),'Reporte de no-show cancelado.')}>CANCELAR NO-SHOW</button>}</>}{a.noShow&&Number(a.noShow.reported_pair_id)===Number(d.pair.id)&&a.noShow.status==='pending'&&<div className="actions">{isV3&&<button className="button danger" onClick={()=>confirm('¿Reconocés que tu pareja no pudo presentarse? Se aplicará el incumplimiento inmediatamente.')&&run(()=>api.patch(`/assignments/${a.id}/no-show/accept`),'No-show reconocido y resuelto.')}>RECONOCER NO-SHOW</button>}<button className="button secondary" onClick={()=>run(()=>api.patch(`/assignments/${a.id}/no-show/contest`),'No-show objetado.')}>OBJETAR NO-SHOW</button></div>}<hr/><label>Reportar a<select value={report.target} onChange={e=>setReport({...report,target:e.target.value})}><option value="pair">Pareja rival</option>{a.rival.members.map(m=><option key={m.id} value={`user:${m.id}`}>{m.first_name} {m.last_name}</option>)}</select></label><label>Motivo<select value={report.reason} onChange={e=>setReport({...report,reason:e.target.value})}><option value="misconduct">Mala conducta</option><option value="violence">Violencia</option><option value="threats">Amenazas</option><option value="coordination_refusal">Negativa a coordinar</option><option value="other">Otro</option></select></label><label>Detalle<textarea value={report.details} onChange={e=>setReport({...report,details:e.target.value})}/></label><button onClick={()=>run(()=>api.post('/discipline-reports',{assignmentId:a.id,...(String(report.target).startsWith('user:')?{targetUserId:Number(report.target.split(':')[1])}:{targetPairId:a.rival.id}),reason:report.reason,details:report.details}),'Reporte disciplinario registrado.')}>ENVIAR REPORTE</button></article>
    </div>:d.pair.competition_state==='paused'?<div className="empty">Tu pareja está inactiva y no recibe asignaciones.{d.pair.auto_reactivate_at?<p>Reactivación automática: {fmt(d.pair.auto_reactivate_at)}.</p>:<p>Podés reactivarla desde <Link to="/pareja">Mi pareja</Link>.</p>}</div>:<div className="empty">La rueda está buscando tu próximo rival. No corre ningún plazo hasta que exista una asignación.</div>}
    {(d.reportableRecent||[]).length>0&&<section className="page-section"><div className="section-heading"><div><span className="eyebrow">VENTANA DE 15 DÍAS</span><h2>Reportar un incidente de un partido reciente</h2></div></div><article className="card"><label>Partido<select value={recentReport.assignmentId} onChange={e=>setRecentReport({...recentReport,assignmentId:e.target.value,target:'pair'})}><option value="">Elegir partido</option>{d.reportableRecent.map(x=><option key={x.id} value={x.id}>vs. {x.rival.players} · cerrado {fmt(x.closed_at)}</option>)}</select></label>{selectedRecent&&<><label>Reportar a<select value={recentReport.target} onChange={e=>setRecentReport({...recentReport,target:e.target.value})}><option value="pair">Pareja rival</option>{selectedRecent.rival.members.map(m=><option key={m.id} value={`user:${m.id}`}>{m.first_name} {m.last_name}</option>)}</select></label><label>Motivo<select value={recentReport.reason} onChange={e=>setRecentReport({...recentReport,reason:e.target.value})}><option value="misconduct">Mala conducta</option><option value="violence">Violencia</option><option value="threats">Amenazas</option><option value="coordination_refusal">Negativa a coordinar</option><option value="no_show">No-show</option><option value="other">Otro</option></select></label><label>Detalle<textarea value={recentReport.details} onChange={e=>setRecentReport({...recentReport,details:e.target.value})}/></label><button disabled={!recentReport.assignmentId||(recentReport.reason==='other'&&!recentReport.details.trim())} onClick={()=>run(()=>api.post('/discipline-reports',{assignmentId:Number(recentReport.assignmentId),...(String(recentReport.target).startsWith('user:')?{targetUserId:Number(recentReport.target.split(':')[1])}:{targetPairId:selectedRecent.rival.id}),reason:recentReport.reason,details:recentReport.details}),'Reporte disciplinario registrado.')}>ENVIAR REPORTE DEL PARTIDO RECIENTE</button></>}</article></section>}
    <Notice n={n}/><section><h2>Qué acaba de pasar</h2><div className="stack">{d.recentEvents.map((e,i)=><article className="card compact" key={i}><b>{eventText(e)}</b><span>{fmt(e.created_at)}</span></article>)}</div></section>
  </main></Layout>
}
function Notifications(){const[rows,setRows]=useState([]);async function load(){setRows((await api.get('/me/notifications')).data||[])}useEffect(()=>{load()},[]);return <Layout><main className="page notifications-page"><div className="page-title"><div><span className="eyebrow">CENTRO DE AVISOS</span><h1>Avisos</h1><p>Todo lo importante de tu actividad queda guardado acá, aunque también llegue por WhatsApp.</p></div><div className="notification-counter"><strong>{rows.filter(n=>!n.read_at).length}</strong><span>sin leer</span></div></div><div className="stack notifications-stack">{rows.map(n=><article className={`card compact notification-row ${n.read_at?'read':'unread'}`} key={n.id} onClick={()=>!n.read_at&&api.patch(`/me/notifications/${n.id}/read`).then(load)}><div><span className="notification-dot"/><div><b>{n.title}</b><p>{n.body}</p></div></div><small>{fmt(n.created_at)}</small></article>)}{!rows.length&&<div className="empty">Todavía no tenés avisos. Cuando LA RED necesite algo de vos, va a aparecer acá.</div>}</div></main></Layout>}
function Account(){const[u,setU]=useState(),[phone,setPhone]=useState(''),[code,setCode]=useState(''),[n,setN]=useState(),[sent,setSent]=useState(false),[docs,setDocs]=useState({front:null,back:null}),[uploadingDocs,setUploadingDocs]=useState(false),[docsKey,setDocsKey]=useState(0);async function load(){try{setU((await api.get('/me')).data)}catch(e){setN({type:'error',text:err(e)})}}useEffect(()=>{load()},[]);async function request(){try{await api.post('/me/phone/request',{phone});setSent(true);setN({text:'Enviamos un código al nuevo WhatsApp.'})}catch(e){setN({type:'error',text:err(e)})}}async function confirmPhone(){try{await api.post('/me/phone/confirm',{code});setN({text:'WhatsApp actualizado y auditado.'});setSent(false);setPhone('');setCode('');await load()}catch(e){setN({type:'error',text:err(e)})}}async function resendIdentity(){if(!docs.front||!docs.back){setN({type:'error',text:'Elegí una foto del frente y otra del dorso.'});return;}try{setUploadingDocs(true);const data=new FormData();data.append('dniFront',docs.front);data.append('dniBack',docs.back);await api.post('/me/identity-documents',data);setDocs({front:null,back:null});setDocsKey(k=>k+1);setN({text:'Recibimos las nuevas fotos. Tu identidad volvió a quedar lista para revisión.'});await load()}catch(e){setN({type:'error',text:err(e)})}finally{setUploadingDocs(false)}}return <Layout><main className="page account-page"><div className="page-title"><div><span className="eyebrow">PERFIL Y SEGURIDAD</span><h1>Mi cuenta</h1><p>Tus datos privados, estado de identidad y canales de contacto.</p></div></div><div className="account-grid">{u&&<article className="card account-profile-card"><div className="account-person"><span>{[u.first_name,u.last_name].filter(Boolean).map(v=>v[0]).join('').slice(0,2).toUpperCase()}</span><div><small>JUGADOR</small><h2>{u.first_name} {u.last_name}</h2></div></div><div className="account-meta"><div><small>IDENTIDAD</small><strong>{u.verification_status==='verified'?'Verificada':'Pendiente'}</strong></div><div><small>CATEGORÍA INDIVIDUAL</small><strong>{u.current_category_number?`${u.current_category_number}ª`:'Sin categoría'}</strong></div></div><p className="privacy-note">Tu DNI y tu teléfono no aparecen en perfiles públicos ni ranking.</p></article>}<article className="card account-security-card"><span className="eyebrow">SEGURIDAD</span><h2>Cambiar WhatsApp</h2><p className="card-intro">El número nuevo se confirma con un código antes de reemplazar el actual.</p><label>Nuevo número<input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="Ej. 3329..."/></label><button onClick={request}>ENVIAR CÓDIGO</button>{sent&&<div className="phone-confirm-box"><label>Código<input value={code} onChange={e=>setCode(e.target.value)}/></label><button className="button primary" onClick={confirmPhone}>CONFIRMAR CAMBIO</button></div>}</article></div>{u?.verification_status==='pending'&&<section className={`card identity-resubmit-card ${u.identity_resubmit_reason?'needs-resubmit':''}`}><span className="eyebrow">{u.identity_resubmit_reason?'ACCIÓN REQUERIDA':'VERIFICACIÓN DE IDENTIDAD'}</span><h2>{u.identity_resubmit_reason?'Necesitamos nuevas fotos de tu DNI':'¿Subiste una foto incorrecta?'}</h2><p>{u.identity_resubmit_reason?<>Administración pidió que vuelvas a enviar frente y dorso. <b>Motivo:</b> {u.identity_resubmit_reason}</>:<>Mientras tu identidad siga pendiente podés reemplazar el frente y dorso sin crear otra cuenta. Las nuevas fotos reemplazan las anteriores.</>}</p><div className="identity-resubmit-grid" key={docsKey}><label>Nuevo frente<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={e=>setDocs(d=>({...d,front:e.target.files?.[0]||null}))}/></label><label>Nuevo dorso<input type="file" accept="image/jpeg,image/png,image/webp" capture="environment" onChange={e=>setDocs(d=>({...d,back:e.target.files?.[0]||null}))}/></label></div><div className="identity-resubmit-actions"><button className="button primary" disabled={uploadingDocs} onClick={resendIdentity}>{uploadingDocs?'ENVIANDO...':'REENVIAR FRENTE Y DORSO'}</button><small>JPG, PNG o WEBP · máximo 5 MB por imagen.</small></div></section>}<Notice n={n}/></main></Layout>}

async function openIdentityDocument(userId,side){const r=await api.get(`/admin/identity/${userId}/document/${side}`,{responseType:'blob'});const url=URL.createObjectURL(r.data);const w=window.open(url,'_blank','noopener,noreferrer');if(!w)throw new Error('El navegador bloqueó la apertura de la imagen.');setTimeout(()=>URL.revokeObjectURL(url),60000);}
function Admin(){const[status,setStatus]=useState(),[pending,setPending]=useState([]),[venues,setVenues]=useState([]),[disputes,setDisputes]=useState([]),[discipline,setDiscipline]=useState([]),[audit,setAudit]=useState([]),[search,setSearch]=useState(''),[users,setUsers]=useState([]),[venue,setVenue]=useState({active:true}),[n,setN]=useState();async function load(reportError=true){try{const[s,p,v,d,r,a]=await Promise.all([api.get('/admin/status'),api.get('/admin/identity/pending'),api.get('/admin/venues'),api.get('/admin/disputes'),api.get('/admin/discipline'),api.get('/admin/audit',{params:{limit:80}})]);setStatus(s.data);setPending(p.data);setVenues(v.data);setDisputes(d.data);setDiscipline(r.data);setAudit(a.data);return true}catch(e){if(reportError)setN({type:'error',text:err(e)});return false}}useEffect(()=>{load()},[]);async function run(fn,msg){try{await fn();const refreshed=await load(false);setN({text:refreshed?msg:`${msg} El panel no pudo refrescarse automáticamente; recargá la página.`})}catch(e){setN({type:'error',text:err(e)})}}async function find(){try{setUsers((await api.get('/admin/identity/search',{params:{q:search}})).data)}catch(e){setN({type:'error',text:err(e)})}}return <Layout><main className="page admin-page"><span className="eyebrow">ADMINISTRACIÓN</span><h1>{!status?'Estado del sistema pendiente':(status.disputes||0)+(status.pendingIdentity||0)+(status.discipline||0)+(status.outboxFailed||0)>0||!status.whatsapp||status.clockPaused?'Hay excepciones para revisar':'Sin excepciones pendientes'}</h1><p className="lead">El motor resuelve lo determinístico. Acá aparecen solamente identidad, disputas reales, disciplina, canchas, correcciones y salud del sistema.</p><div className="admin-summary"><article className="card"><span>IDENTIDAD</span><strong>{status?.pendingIdentity??'-'}</strong><small>pendientes</small></article><article className="card"><span>DISPUTAS</span><strong>{status?.disputes??'-'}</strong><small>resultados</small></article><article className="card"><span>DISCIPLINA</span><strong>{status?.discipline??'-'}</strong><small>casos abiertos</small></article><article className="card"><span>RUEDA</span><strong>{status?.openAssignments??'-'}</strong><small>partidos abiertos</small></article><article className="card"><span>WHATSAPP</span><strong>{status?.whatsapp?'CONFIG.':'—'}</strong><small>{!status?"sin verificar":status.outboxFailed?`${status.outboxFailed} fallidos`:status.whatsapp?'configurado · entrega no verificada':'sin configurar'}</small>{status?.whatsappConfiguration?.missing?.length>0&&<small>Falta: {status.whatsappConfiguration.missing.join(", ")}</small>}{status?.whatsappConfiguration?.invalid?.length>0&&<small>Revisar: {status.whatsappConfiguration.invalid.join(", ")}</small>}</article><article className="card"><span>RELOJES</span><strong>{!status?'—':status.clockPaused?'PAUSA':'OK'}</strong><small>{!status?'sin verificar':status.clockPaused?'suspendidos':'corriendo'}</small></article></div><div className="actions"><button className="button secondary" onClick={()=>run(()=>api.post('/admin/maintenance'),'Mantenimiento ejecutado.')}>EJECUTAR MANTENIMIENTO</button><button className="button secondary" onClick={()=>run(()=>api.post('/admin/whatsapp/retry'),'Outbox de WhatsApp procesada.')}>REINTENTAR WHATSAPP</button><button className="button danger" onClick={()=>confirm('¿Suspender todos los relojes de la liga?')&&run(()=>api.patch('/admin/system/clock',{paused:true}),'Relojes suspendidos.')}>SUSPENDER RELOJES</button><button className="button secondary" onClick={()=>confirm('¿Reanudar los relojes y extender automáticamente los plazos por el tiempo suspendido?')&&run(()=>api.patch('/admin/system/clock',{paused:false}),'Relojes reanudados.')}>REANUDAR RELOJES</button></div><Notice n={n}/><section><h2>Identidad pendiente</h2>{pending.map(u=><article className="card identity-review" key={u.id}><div><b>{u.first_name} {u.last_name}</b><p>DNI {u.dni} · {u.phone}</p><small>{u.identity_resubmit_reason?`Esperando nuevas fotos · ${u.identity_resubmit_reason}`:u.documents_available?'Frente y dorso disponibles para revisión.':'Faltan documentos de identidad.'}</small></div><div className="identity-doc-actions"><button className="secondary" disabled={!u.documents_available} onClick={()=>openIdentityDocument(u.id,'front').catch(e=>setN({type:'error',text:err(e)}))}>VER FRENTE</button><button className="secondary" disabled={!u.documents_available} onClick={()=>openIdentityDocument(u.id,'back').catch(e=>setN({type:'error',text:err(e)}))}>VER DORSO</button><button className="secondary" onClick={()=>{const reason=window.prompt('Motivo para pedir nuevas fotos (ej: frente borroso, dorso cortado):',u.identity_resubmit_reason||'');if(reason?.trim())run(()=>api.post(`/admin/identity/${u.id}/resubmit`,{reason:reason.trim()}),'Se pidieron nuevas fotos. El jugador fue avisado.')}}>PEDIR NUEVAS FOTOS</button><button disabled={!u.documents_available} onClick={()=>confirm('¿Confirmás que nombre, foto y DNI corresponden a esta persona? Al verificar, las imágenes del DNI se purgan de la base activa.')&&run(()=>api.patch(`/admin/identity/${u.id}`,{status:'verified'}),'Jugador verificado; las imágenes del DNI fueron purgadas de la base activa.')}>VERIFICAR</button><button className="danger" onClick={()=>confirm('Usá RECHAZAR CUENTA solo si la identidad no corresponde o la cuenta no debe habilitarse. ¿Continuar?')&&run(()=>api.patch(`/admin/identity/${u.id}`,{status:'rejected'}),'Cuenta rechazada y documentos purgados de la base activa.')}>RECHAZAR CUENTA</button></div></article>)}{!pending.length&&<div className="empty">No hay identidades pendientes.</div>}</section><section><h2>Buscar / corregir DNI</h2><div className="inline"><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Nombre o DNI"/><button onClick={find}>BUSCAR</button></div>{users.map(u=><IdentityRow key={u.id} u={u} done={load}/>)}</section><section><h2>Disputas reales</h2>{disputes.map(d=><article className="card" key={d.id}><b>Partido #{d.id}</b>{(d.versions||[]).map(v=><div className="card compact" key={v.id}><span>Versión pareja #{v.pair_id} · ganador #{v.winner_pair_id}</span><button onClick={()=>confirm('Esta resolución puede mover ranking y rachas. ¿Confirmar?')&&run(()=>api.patch(`/admin/disputes/${d.id}`,{action:'select',versionId:v.id}),'Disputa resuelta.')}>VALIDAR ESTA</button></div>)}{status?.engine==='wheel-v3'&&d.noShow?<div className="card compact"><div><b>No-show en revisión</b><p>Reportó pareja #{d.noShow.reported_by_pair_id} contra pareja #{d.noShow.reported_pair_id}.</p></div><div className="actions"><button className="secondary" onClick={()=>confirm('¿Cerrar el reporte sin sanción deportiva?')&&run(()=>api.patch(`/admin/disputes/${d.id}`,{action:'no_show_dismiss'}),'No-show cerrado sin sanción.')}>DESCARTAR NO-SHOW</button><button className="danger" onClick={()=>confirm(`¿Marcar incumplimiento de ${d.pair_a_name||'pareja A'}?`)&&run(()=>api.patch(`/admin/disputes/${d.id}`,{action:'no_show_fail',failingPairId:Number(d.pair_a_id)}),'No-show resuelto.')}>INCUMPLIÓ {d.pair_a_name||'PAREJA A'}</button><button className="danger" onClick={()=>confirm(`¿Marcar incumplimiento de ${d.pair_b_name||'pareja B'}?`)&&run(()=>api.patch(`/admin/disputes/${d.id}`,{action:'no_show_fail',failingPairId:Number(d.pair_b_id)}),'No-show resuelto.')}>INCUMPLIÓ {d.pair_b_name||'PAREJA B'}</button></div></div>:status?.engine!=='wheel-v3'&&<button className="danger" onClick={()=>confirm('¿Cerrar sin resultado oficial?')&&run(()=>api.patch(`/admin/disputes/${d.id}`,{action:'void'}),'Partido cerrado void.')}>RECHAZAR AMBAS</button>}</article>)}{!disputes.length&&<div className="empty">No hay disputas reales pendientes.</div>}</section><section><h2>Disciplina</h2>{discipline.map(r=><article className="card compact" key={r.id}><div><b>{r.reason}</b><p>{r.details}</p></div><div><button onClick={()=>run(()=>api.patch(`/admin/discipline/${r.id}`,{status:'reviewed'}),'Marcado revisado.')}>REVISADA</button><button onClick={()=>run(()=>api.patch(`/admin/discipline/${r.id}`,{status:'dismissed'}),'Descartada.')}>DESCARTAR</button><button onClick={()=>run(()=>api.patch(`/admin/discipline/${r.id}`,{status:'resolved'}),'Disciplina resuelta.')}>RESOLVER</button></div></article>)}{!discipline.length&&<div className="empty">No hay casos disciplinarios pendientes.</div>}</section><section><h2>Canchas adheridas / comerciales</h2><p className="muted">Esta lista es para sedes que LA RED decida publicar como adheridas. Los lugares escritos por jugadores en sus partidos no se agregan acá automáticamente.</p><article className="card"><div className="grid2"><label>Nombre<input onChange={e=>setVenue({...venue,name:e.target.value})}/></label><label>Dirección<input onChange={e=>setVenue({...venue,address:e.target.value})}/></label><label>Instagram / web<input placeholder="https://..." onChange={e=>setVenue({...venue,instagram:e.target.value})}/></label><label>Link de reserva<input placeholder="https://..." onChange={e=>setVenue({...venue,bookingUrl:e.target.value})}/></label><label className="check"><input type="checkbox" checked={Boolean(venue.associated)} onChange={e=>setVenue({...venue,associated:e.target.checked})}/><span>Sede asociada / recomendada</span></label><label className="check"><input type="checkbox" checked={Boolean(venue.bookingEnabled)} onChange={e=>setVenue({...venue,bookingEnabled:e.target.checked})}/><span>Preparada para reservas futuras</span></label></div><button onClick={()=>run(()=>api.post('/admin/venues',venue),'Cancha creada.')}>AGREGAR CANCHA</button></article>{venues.map(v=><VenueRow key={v.id} v={v} done={load}/>)}</section><section><h2>Auditoría administrativa</h2><p className="muted">Las decisiones sensibles no se borran: queda quién hizo qué, cuándo y sobre qué objeto.</p><div className="stack">{audit.map(e=><article className="audit-row" key={e.id}><div><b>{e.action}</b><span>{e.target_type}{e.target_id?` #${e.target_id}`:''}</span></div><div><small>{e.admin_name}</small><small>{fmt(e.created_at)}</small></div></article>)}{!audit.length&&<div className="empty">Todavía no hay acciones administrativas auditadas.</div>}</div></section></main></Layout>}
function VenueRow({v,done}){const[form,setForm]=useState({name:v.name||'',address:v.address||'',instagram:v.instagram||'',bookingUrl:v.booking_url||'',associated:Boolean(v.associated),bookingEnabled:Boolean(v.booking_enabled),active:Boolean(v.active),sortOrder:Number(v.sort_order||100)}),[n,setN]=useState();async function save(){try{await api.patch(`/admin/venues/${v.id}`,form);setN({text:'Cancha actualizada.'});await done(false)}catch(e){setN({type:'error',text:err(e)})}}return <article className="card"><div className="grid2"><label>Nombre<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Dirección<input value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/></label><label>Instagram / web<input value={form.instagram} onChange={e=>setForm({...form,instagram:e.target.value})}/></label><label>Link de reserva<input value={form.bookingUrl} onChange={e=>setForm({...form,bookingUrl:e.target.value})}/></label><label>Orden<input type="number" value={form.sortOrder} onChange={e=>setForm({...form,sortOrder:Number(e.target.value)})}/></label><label className="check"><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/><span>Activa</span></label><label className="check"><input type="checkbox" checked={form.associated} onChange={e=>setForm({...form,associated:e.target.checked})}/><span>Sede adherida / visible públicamente</span></label><label className="check"><input type="checkbox" checked={form.bookingEnabled} onChange={e=>setForm({...form,bookingEnabled:e.target.checked})}/><span>Mostrar reserva</span></label></div><button onClick={save}>GUARDAR CAMBIOS</button><Notice n={n}/></article>}
function IdentityRow({u,done}){const[dni,setDni]=useState(u.dni),[n,setN]=useState();async function save(){if(!confirm(`Corregir DNI de ${u.first_name} ${u.last_name} a ${dni}?`))return;try{await api.patch(`/admin/identity/${u.id}/dni`,{dni});setN({text:'Corregido y auditado.'});done()}catch(e){setN({type:'error',text:err(e)})}}return <article className="card compact"><div><b>{u.first_name} {u.last_name}</b><p>{u.phone} · {u.verification_status}</p></div><div className="inline"><input value={dni} onChange={e=>setDni(e.target.value)}/><button onClick={save}>CORREGIR DNI</button></div><Notice n={n}/></article>}
function Install(){return <Layout><main className="page install-page"><div className="page-title"><div><span className="eyebrow">PWA · MÓVIL</span><h1>Instalar LA RED</h1><p>Usá la misma liga desde el navegador o agregala a la pantalla de inicio como una app.</p></div></div><div className="grid3 install-grid"><article className="card"><span className="install-step">01</span><h2>Abrí LA RED</h2><p>Entrá desde Safari en iPhone o Chrome en Android.</p></article><article className="card"><span className="install-step">02</span><h2>Agregar a inicio</h2><p>Usá la opción “Agregar a pantalla de inicio” o “Instalar aplicación”.</p></article><article className="card"><span className="install-step">03</span><h2>Entrá normalmente</h2><p>Tu cuenta, ranking, pareja y rueda son exactamente los mismos.</p></article></div></main></Layout>}
function Protected({children,adminOnly=false}){const u=user();if(!u)return <Auth/>;if(adminOnly&&u.role!=='admin')return <Layout><main className="page"><div className="empty">Acceso restringido.</div></main></Layout>;return children;}
export default function App(){return <Routes><Route path="/" element={<Home/>}/><Route path="/ingresar" element={<Auth/>}/><Route path="/admin-la-red" element={<AdminLogin/>}/><Route path="/recuperar" element={<Recovery/>}/><Route path="/ranking" element={<Ranking/>}/><Route path="/proximos" element={<Upcoming/>}/><Route path="/parejas/:id" element={<PairProfile/>}/><Route path="/instalar" element={<Install/>}/><Route path="/liga" element={<Protected><League/></Protected>}/><Route path="/pareja" element={<Protected><PairManager/></Protected>}/><Route path="/notificaciones" element={<Protected><Notifications/></Protected>}/><Route path="/cuenta" element={<Protected><Account/></Protected>}/><Route path="/admin" element={<Protected adminOnly><Admin/></Protected>}/><Route path="*" element={<Home/>}/></Routes>}
